//! Lombok: members generated by annotations must be understood by completion, hover, definition
//! and diagnostics, and the generated shapes follow Lombok's naming rules.

use java_ide::completion::{self, CompletionSettings};
use java_ide::{diagnostics, hover, navigation};
use java_semantic::fixture::Fixture;

const PERSON: &str = r#"package app;

import lombok.Data;
import lombok.Builder;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;
import java.util.List;

@Data
@Builder(toBuilder = true)
@NoArgsConstructor
@AllArgsConstructor
public class Person {
    private final long id = 1;
    private String name;
    private int age;
    private boolean active;
    private Boolean verified;
    private List<String> tags;
}
"#;

fn labels(files: &[(&str, &str)]) -> Vec<String> {
    let mut fixture = Fixture::new(files);
    let (file, offset) = fixture.cursor();
    let settings = CompletionSettings {
        snippets: true,
        additional_edits: true,
    };
    completion::completions_repairing(&mut fixture.db, file, offset, settings)
        .into_iter()
        .map(|item| item.label)
        .collect()
}

fn use_site(body: &str) -> String {
    format!(
        "package app;\nimport java.util.*;\npublic class Use {{\n  void m(Person p) {{\n    {body}\n  }}\n}}\n"
    )
}

fn errors(files: &[(&str, &str)], file: &str) -> Vec<String> {
    let fixture = Fixture::new(files);
    let id = fixture.file(file);
    diagnostics::diagnostics(&fixture.db, id)
        .iter()
        .filter(|d| d.severity == Some(lsp_types::DiagnosticSeverity::ERROR))
        .map(diagnostics::describe)
        .collect()
}

#[test]
fn data_generates_getters_and_setters_with_lombok_naming() {
    let found = labels(&[("Person.java", PERSON), ("Use.java", &use_site("p.$0"))]);
    for expected in [
        "getName",
        "setName",
        "getAge",
        "setAge",
        "isActive",
        "setActive",
        "getVerified",
        "setVerified",
        "getTags",
        "setTags",
        "getId",
        "toBuilder",
    ] {
        assert!(
            found.contains(&expected.to_string()),
            "missing {expected}: {found:?}"
        );
    }
    assert!(
        !found.contains(&"setId".to_string()),
        "final field has no setter: {found:?}"
    );
    assert!(
        !found.contains(&"getActive".to_string()),
        "primitive boolean uses is: {found:?}"
    );
    assert!(
        !found.contains(&"isVerified".to_string()),
        "boxed Boolean uses get: {found:?}"
    );
}

#[test]
fn getter_return_types_are_the_field_types() {
    let source = use_site("p.getTags().$0");
    let fixture_files = [("Person.java", PERSON), ("Use.java", source.as_str())];
    let fixture = Fixture::new(&fixture_files);
    if !fixture.has_stdlib() {
        return;
    }
    drop(fixture);
    let found = labels(&fixture_files);
    assert!(
        found.contains(&"size".to_string()) && found.contains(&"add".to_string()),
        "{found:?}"
    );
}

#[test]
fn builder_chains_and_builds_the_annotated_class() {
    let found = labels(&[
        ("Person.java", PERSON),
        (
            "Use.java",
            &use_site("Person.builder().name(\"a\").age(3).$0"),
        ),
    ]);
    for expected in ["tags", "active", "verified", "build"] {
        assert!(
            found.contains(&expected.to_string()),
            "missing {expected}: {found:?}"
        );
    }
    assert!(
        !found.contains(&"id".to_string()),
        "initialised final is not a builder field: {found:?}"
    );

    let built = labels(&[
        ("Person.java", PERSON),
        (
            "Use.java",
            &use_site("Person.builder().name(\"a\").build().$0"),
        ),
    ]);
    assert!(built.contains(&"getName".to_string()), "{built:?}");
}

#[test]
fn generated_constructors_replace_the_implicit_one() {
    let files = [
        ("Person.java", PERSON),
        (
            "Use.java",
            "package app;\nimport java.util.*;\npublic class Use {\n  void m() {\n    Person a = new Person();\n    Person b = new Person(\"n\", 1, true, Boolean.TRUE, new ArrayList<String>());\n    a.setName(\"x\");\n    String s = b.getName();\n    boolean on = b.isActive();\n  }\n}\n",
        ),
    ];
    if !Fixture::new(&files).has_stdlib() {
        return;
    }
    assert_eq!(errors(&files, "Use.java"), Vec::<String>::new());
}

#[test]
fn a_wrong_call_on_a_lombok_class_is_still_reported() {
    let files = [
        ("Person.java", PERSON),
        (
            "Use.java",
            "package app;\npublic class Use {\n  void m(Person p) {\n    p.setName(1, 2);\n  }\n}\n",
        ),
    ];
    if !Fixture::new(&files).has_stdlib() {
        return;
    }
    assert!(!errors(&files, "Use.java").is_empty());
}

#[test]
fn nothing_is_generated_without_a_lombok_import() {
    let source = "package app;\n@Data\npublic class Plain { private String name; }\n";
    let found = labels(&[
        ("Plain.java", source),
        (
            "Use.java",
            "package app;\npublic class Use {\n  void m(Plain p) {\n    p.$0\n  }\n}\n",
        ),
    ]);
    assert!(!found.contains(&"getName".to_string()), "{found:?}");
}

#[test]
fn accessors_chain_fluent_and_prefix_change_names() {
    let account = r#"package app;
import lombok.*;
import lombok.experimental.Accessors;

@Getter
@Setter
@Accessors(chain = true, prefix = "m")
public class Account {
    private String mOwner;
    private int balance;
}

@Getter
@Accessors(fluent = true)
class Point {
    private int x;
}
"#;
    let found = labels(&[
        ("Account.java", account),
        (
            "Use.java",
            "package app;\npublic class Use {\n  void m(Account a) {\n    a.setOwner(\"x\").setBalance(1).$0\n  }\n}\n",
        ),
    ]);
    assert!(
        found.contains(&"getOwner".to_string()) && found.contains(&"getBalance".to_string()),
        "{found:?}"
    );
    let fluent = labels(&[
        ("Account.java", account),
        (
            "Use.java",
            "package app;\npublic class Use {\n  void m(Point p) {\n    p.$0\n  }\n}\n",
        ),
    ]);
    assert!(
        fluent.contains(&"x".to_string()) && !fluent.contains(&"getX".to_string()),
        "{fluent:?}"
    );
}

#[test]
fn an_explicit_method_suppresses_the_generated_one() {
    let source = "package app;\nimport lombok.Getter;\n@Getter\npublic class Box {\n  private int size;\n  public long getSize() { return size; }\n}\n";
    let fixture = Fixture::new(&[
        ("Box.java", source),
        ("Use.java", "package app;\npublic class Use {\n  void m(Box b) {\n    long v = b.getSize$0();\n  }\n}\n"),
    ]);
    let (file, offset) = fixture.cursor();
    let text = match hover::hover(&fixture.db, file, offset)
        .expect("hover")
        .contents
    {
        lsp_types::HoverContents::Markup(markup) => markup.value,
        _ => panic!(),
    };
    assert!(text.contains("long getSize()"), "{text}");
}

#[test]
fn hover_and_definition_on_a_generated_getter_point_at_the_field() {
    let files = [
        ("Person.java", PERSON),
        ("Use.java", &use_site("String n = p.getNa$0me();")),
    ];
    let fixture = Fixture::new(&files);
    let (file, offset) = fixture.cursor();
    let text = match hover::hover(&fixture.db, file, offset)
        .expect("hover")
        .contents
    {
        lsp_types::HoverContents::Markup(markup) => markup.value,
        _ => panic!(),
    };
    assert!(text.contains("String getName()"), "{text}");
    assert!(text.contains("Lombok"), "{text}");
    let links = navigation::definition(&fixture.db, file, offset);
    assert_eq!(links.len(), 1, "{links:?}");
    assert!(links[0].target_uri.as_str().ends_with("Person.java"));
    // The field `name` is declared on line 14 (zero-based).
    assert_eq!(links[0].target_selection_range.start.line, 14);
}

#[test]
fn value_makes_fields_private_and_adds_an_all_args_constructor() {
    let source = "package app;\nimport lombok.Value;\n@Value\npublic class Money {\n  long cents;\n  String currency;\n}\n";
    let files = [
        ("Money.java", source),
        (
            "Use.java",
            "package app;\npublic class Use {\n  void m() {\n    Money m = new Money(5L, \"USD\");\n    long c = m.getCents();\n    String s = m.$0\n  }\n}\n",
        ),
    ];
    let found = labels(&files);
    assert!(found.contains(&"getCurrency".to_string()), "{found:?}");
    assert!(!found.contains(&"setCents".to_string()), "{found:?}");
    assert!(
        !found.contains(&"cents".to_string()),
        "fields are private: {found:?}"
    );
}

#[test]
fn slf4j_declares_a_log_field_and_required_args_constructor_uses_final_fields() {
    let source = "package app;\nimport lombok.*;\nimport lombok.extern.slf4j.Slf4j;\n@Slf4j\n@RequiredArgsConstructor\npublic class Service {\n  private final String repo;\n  private int cache;\n  void run() {\n    $0\n  }\n}\n";
    let found = labels(&[("Service.java", source)]);
    assert!(found.contains(&"log".to_string()), "{found:?}");
    let files = [(
        "Service.java",
        source.replace("    $0\n", "").as_str().to_owned(),
    )];
    let use_source = "package app;\npublic class Use {\n  Service s = new Service(\"r\");\n}\n";
    let pair = [
        ("Service.java", files[0].1.as_str()),
        ("Use.java", use_source),
    ];
    if Fixture::new(&pair).has_stdlib() {
        assert_eq!(errors(&pair, "Use.java"), Vec::<String>::new());
    }
}

#[test]
fn super_builder_chains_parent_and_child_fields() {
    let animal = "package app;\nimport lombok.experimental.SuperBuilder;\n@SuperBuilder\npublic class Animal {\n  private String name;\n}\n";
    let dog = "package app;\nimport lombok.experimental.SuperBuilder;\n@SuperBuilder\npublic class Dog extends Animal {\n  private int tricks;\n}\n";
    let use_source = "package app;\npublic class Use {\n  void m() {\n    Dog d = Dog.builder().name(\"rex\").tricks(2).build();\n    Dog.builder().$0\n  }\n}\n";
    let found = labels(&[
        ("Animal.java", animal),
        ("Dog.java", dog),
        ("Use.java", use_source),
    ]);
    for expected in ["name", "tricks", "build"] {
        assert!(
            found.contains(&expected.to_string()),
            "missing {expected}: {found:?}"
        );
    }
}

#[test]
fn singular_generates_adder_and_bulk_methods() {
    let source = "package app;\nimport lombok.*;\nimport java.util.List;\n@Builder\npublic class Order {\n  @Singular private List<String> items;\n}\n";
    let found = labels(&[
        ("Order.java", source),
        (
            "Use.java",
            "package app;\npublic class Use {\n  void m() {\n    Order.builder().$0\n  }\n}\n",
        ),
    ]);
    for expected in ["item", "items", "clearItems", "build"] {
        assert!(
            found.contains(&expected.to_string()),
            "missing {expected}: {found:?}"
        );
    }
}

/// Edits to a Lombok class must show up in other files without restarting the server.
#[test]
fn editing_a_lombok_class_updates_generated_members_elsewhere() {
    use java_syntax::Position as SyntaxPosition;
    let widget = "package app;\nimport lombok.Getter;\n@Getter\npublic class Widget {\n  private int size;\n}\n";
    let use_site = "package app;\npublic class Use {\n  void m(Widget w) {\n    w.\n  }\n}\n";
    let mut fixture = Fixture::new(&[("Widget.java", widget), ("Use.java", use_site)]);
    let settings = CompletionSettings {
        snippets: true,
        additional_edits: true,
    };
    let use_path = fixture.root.join("Use.java");
    let widget_path = fixture.root.join("Widget.java");
    let db = &mut fixture.db;
    let use_file = db.open_document(&use_path, use_site.to_string(), 1);
    let widget_file = db.open_document(&widget_path, widget.to_string(), 1);
    let offset = db.text(use_file).unwrap().find("w.").unwrap() as u32 + 2;
    let names = |db: &mut java_semantic::db::Db| -> Vec<String> {
        completion::completions_repairing(db, use_file, offset, settings)
            .into_iter()
            .map(|item| item.label)
            .collect()
    };
    let before = names(db);
    assert!(before.contains(&"getSize".to_string()), "{before:?}");
    assert!(!before.contains(&"getLabel".to_string()));

    // Add a field below `size`: its getter appears.
    db.edit_document(widget_file, 2, |source| {
        source.apply_change(
            SyntaxPosition::new(4, 0),
            SyntaxPosition::new(4, 0),
            "  private String label;\n",
            2,
        )
    });
    let after_field = names(db);
    assert!(
        after_field.contains(&"getLabel".to_string()),
        "{after_field:?}"
    );

    // Add `@Setter` above the class: setters appear.
    db.edit_document(widget_file, 3, |source| {
        source.apply_change(
            SyntaxPosition::new(2, 0),
            SyntaxPosition::new(2, 0),
            "@lombok.Setter\n",
            3,
        )
    });
    let after_annotation = names(db);
    assert!(
        after_annotation.contains(&"setSize".to_string()),
        "{after_annotation:?}"
    );

    // Removing `@Getter` (now on line 3) removes the getters again.
    db.edit_document(widget_file, 4, |source| {
        source.apply_change(SyntaxPosition::new(3, 0), SyntaxPosition::new(4, 0), "", 4)
    });
    let after_removal = names(db);
    assert!(
        !after_removal.contains(&"getSize".to_string()),
        "{after_removal:?}"
    );
}
